import{_ as d,o as e,c as r,a2 as o}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"ホットキー","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/hotkeys.md","filePath":"ja-JP/user-guide/hotkeys.md","lastUpdated":1785993908000}'),a={name:"ja-JP/user-guide/hotkeys.md"};function c(l,t,s,n,h,i){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="ホットキー" tabindex="-1">ホットキー <a class="header-anchor" href="#ホットキー" aria-label="Permalink to &quot;ホットキー&quot;">​</a></h1><p>以下のグローバルホットキーとアプリ内ホットキーは、すべて <strong>設定 → ホットキー</strong> から再設定できます。ここに示しているのは既定値です。設定 UI 自体については <a href="./settings/hotkeys-page.html">設定 → ホットキーページ</a> を参照してください。</p><h2 id="グローバルホットキー" tabindex="-1">グローバルホットキー <a class="header-anchor" href="#グローバルホットキー" aria-label="Permalink to &quot;グローバルホットキー&quot;">​</a></h2><table tabindex="0"><thead><tr><th>アクション</th><th>既定値</th><th>補足</th></tr></thead><tbody><tr><td>クイックウィンドウの切り替え</td><td><code>Ctrl</code> のダブルタップ</td><td>ダブルタップの代わりに、<code>Alt+Space</code> のような完全なキーの組み合わせに設定することもできます。</td></tr><tr><td>クイック切り替え</td><td><code>Ctrl+G</code></td><td>対応するファイルダイアログで、対応ファイルマネージャーまたはクイックパネルから最後に取得したフォルダーへ移動します。インライン検索が空なら、その移動先も結果として表示されます。</td></tr><tr><td>次のアイテムを選択</td><td><code>Ctrl+N</code></td><td>実際の下矢印キーとしても機能します。<a href="./settings/quick-panel.html">クイックパネル</a>では1つのグループではなくタブ全体を移動し、グループの末尾に来ると次のグループへ入っていきます。</td></tr><tr><td>前のアイテムを選択</td><td><code>Ctrl+P</code></td><td>実際の上矢印キーとしても機能します。クイックパネルでも同じくグループをまたいでタブ全体を移動します。</td></tr><tr><td>検索結果 1~9 へジャンプ</td><td><code>Ctrl</code> + 数字</td><td>修飾キーは設定可能で、数字は常に 1~9 です。クイックウィンドウでは、表示されている各検索結果の隣にショートカットが小さなバッジとして表示されるため、行数を数える必要はありません。</td></tr><tr><td>アクションメニューを開く</td><td><code>Ctrl+O</code></td><td>選択した検索結果に対する実際の右矢印キーとしても機能します。</td></tr><tr><td>選択項目から補完</td><td><code>Ctrl+Tab</code></td><td>クイックウィンドウでは、選択されている検索結果の名前/パスで検索ボックスを埋めます。</td></tr><tr><td>QuickLook プレビュー</td><td><code>Alt+P</code></td><td>選択した検索結果のプレビューパネルを切り替えます。<a href="./settings/quick-panel.html">クイックパネル</a>も同じキーを使い、プレビューは自分の左右のうち収まるほうの側にドッキングします。</td></tr><tr><td>キーワード履歴を前へ</td><td><code>Alt+Up</code></td><td>最近入力したクエリを過去にさかのぼって順に表示します。</td></tr><tr><td>キーワード履歴を次へ</td><td><code>Alt+Down</code></td><td>最近入力したクエリを新しい方向に順に表示します。</td></tr><tr><td>キーワード履歴のエントリを削除</td><td><code>Ctrl+Delete</code></td><td></td></tr><tr><td>フルウィンドウを開く</td><td><em>(なし)</em></td><td>現在のクエリを引き継いだまま、フルウィンドウを直接開きます。<a href="#検索ボックスのロゴアイコン">クイックウィンドウ自身のロゴ</a>を左クリックして開いたメニューから「メインウィンドウを表示」を選ぶのと同じ効果を、その手順を踏まずに実現します。既定では割り当てられていません。<strong>設定 → ホットキー</strong> から設定してください。</td></tr><tr><td>ウィンドウを閉じない</td><td><code>Ctrl+T</code></td><td>フォーカスが他へ移っても閉じないようにします。ほかのウィンドウからコピーした文字を集めてクエリを組み立てるためで、閉じるたびに検索ボックスが空になるのを防ぎます。今回の呼び出しの間だけ有効で、次に閉じたときに解除されます。クイックウィンドウではロゴを中クリックしても同じことができ、有効な間はロゴが明るくなります。表示されているがフォーカスがない状態で呼び出しキーを押すと、閉じるのではなく前面に戻します。<a href="./settings/quick-panel.html">クイックパネル</a>も同じキーを使い、専用のピン留めボタンが目印になります。</td></tr><tr><td>クイックパネルの表示/非表示</td><td><code>Ctrl+F2</code></td><td><a href="./settings/quick-panel.html">クイックパネル</a>を、前面にあるウィンドウの右下隅にドッキングして開きます。すでに開いていれば閉じます。開いた後は、「1〜9番目の結果へジャンプ」の修飾キーを押しながら 1〜9 を押すとワークスペースを切り替えられます。</td></tr></tbody></table><h2 id="検索ボックスのロゴアイコン" tabindex="-1">検索ボックスのロゴアイコン <a class="header-anchor" href="#検索ボックスのロゴアイコン" aria-label="Permalink to &quot;検索ボックスのロゴアイコン&quot;">​</a></h2><p>検索ボックス内の小さなロゴアイコン (ウィンドウによって左側または右側に表示) は、<a href="./getting-started.html#_3-つのウィンドウ">3 つのウィンドウ</a>それぞれで異なる動作をします:</p><ul><li><p><strong>クイックウィンドウ</strong> — (動かさずに) 左クリックすると、トレイアイコンを右クリックしたときに表示されるものと同じメニュー (メインウィンドウを表示、ホットキーの切り替え、設定、バージョン情報、クリーン終了、終了) がカーソル位置に表示されます。このメニューの「メインウィンドウを表示」項目も、現在入力しているクエリをそのまま引き継ぎます。クリックしてドラッグすると、検索バーの他の部分をドラッグするのと同じようにウィンドウを移動できます。ドラッグ中に <strong>Ctrl</strong> を押し続ける (バーとロゴのどちらでも、またドラッグの途中で Ctrl の押し下げを切り替えても可) と、移動を垂直方向のみに制限できます。これは、横方向にずらさずにウィンドウを上下に微調整したいときに便利です。右クリックすると、ウィンドウを既定の画面位置 (サイズではありません) にリセットします。これは初回起動時に中央に配置されるのと同じ位置です。ホバー時のツールチップで、これら 3 つの動作すべてが説明されます。</p><p>記憶される位置は、絶対的な画面座標ではなく、ウィンドウが最後に表示されていたモニターを基準にした相対位置です。別のモニター (または解像度や DPI スケーリングが異なるモニター) で再度呼び出しても、画面外にはみ出したり誤ったディスプレイに表示されたりせず、そのモニター上の対応する位置に開き直します。</p></li><li><p><strong>インラインウィンドウ</strong> — ウィンドウがネイティブの開く/保存/フォルダーの参照ダイアログにドッキングされている場合にのみクリック可能です。左クリックすると、下記の専用トリガーと同様に<a href="#クイックナビゲーション-マウス">クイックナビゲーション</a>を開きます。単純なエクスプローラーウィンドウやデスクトップにドッキングしている場合はクリックできません。その場合は移動先として役立つものが何もないためです。ホバー時のハイライトやツールチップも表示されないため、クリックできそうに見えて何も起きない、という状態にはなりません。</p></li><li><p><strong>メインウィンドウ</strong> — ここではロゴは純粋に装飾のみで、クリックしても何も起こりません。</p></li></ul><h2 id="クイックナビゲーション-マウス" tabindex="-1">クイックナビゲーション (マウス) <a class="header-anchor" href="#クイックナビゲーション-マウス" aria-label="Permalink to &quot;クイックナビゲーション (マウス)&quot;">​</a></h2><p>既定で有効になっており、トリガーごとに設定でオン/オフを切り替えられます:</p><ul><li>デスクトップ上またはエクスプローラーウィンドウ内の空白部分を <strong>ダブルクリック</strong> すると、クイックナビゲーションが起動します。</li><li>デスクトップ上またはエクスプローラーウィンドウ内の空白部分、対応するサードパーティ製ファイルマネージャー (Directory Opus、Total Commander、XYplorer、Files など) のファイルリスト、あるいはネイティブの開く/保存/フォルダーの参照ダイアログを <strong>ミドルクリック</strong> すると、クイックナビゲーションが起動します。それ以外のこれらのウィンドウはミドルクリックにのみ反応します。ダブルクリックはすでに「これを開く」を意味するため、ダブルクリックへの割り当ては変更されません。各連携でどこまでカバーされるかは<a href="./file-manager-support.html">対応ファイルマネージャー</a>を参照してください。</li><li>インライン検索ウィンドウがネイティブの開く/保存/フォルダーの参照ダイアログにドッキングされている場合、そのロゴをクリックすることでもクイックナビゲーションが起動します — 上記の<a href="#検索ボックスのロゴアイコン">検索ボックスのロゴアイコン</a>を参照してください。</li></ul><p>これらのいずれかのトリガーを操作すると、お気に入り・履歴・設定済みのクイックアクセスフォルダーのカスケードメニューが表示されます (<a href="./settings/favorites.html">設定 → お気に入り</a> と <a href="./settings/history.html">設定 → 履歴</a> を参照)。プラグインも独自の項目をここに追加できます。例えば、<code>wincmd.ini</code> で設定していれば Total Commander 自身の Directory Hotlist、Directory Opus 自身のお気に入りメニュー、「クイックナビゲーションに表示」フラグが付いた<a href="./instant-answers.html#カスタムコマンド">カスタムコマンド</a> (<code>/</code> 区切りのパスを指定してサブメニューにネストすることも可能) などです。それぞれの連携元プラグインは、メニューのルートに独自のラベル付きセクションを持ち、そのセクションが表示される順序は自由に設定できます — 詳しくは<a href="./settings/general.html#クイックナビゲーション">設定 → 一般 → クイックナビゲーション</a>を参照してください。フォルダーをクリックすると対象ウィンドウでそのフォルダーへ移動し、ファイルをクリックした場合もそこへ移動しますが、ファイルを開くのではなく、それが含まれるフォルダー内でそのファイルが選択された状態になります。唯一の例外はデスクトップです。デスクトップにはナビゲート対象となる既存のウィンドウペインがないため、フォルダーやファイルはダブルクリックしたときと同じように直接開かれます。特にファイルダイアログの内部では、ファイルをクリックするとダイアログがそのファイルのフォルダーへジャンプするだけで、意図的に開く/保存を自動的に確定することは決してありません。</p><p>このメニューを実際に構築しているのは <strong>Folder Cascader</strong> プラグインです。お気に入りと履歴 (それぞれ個別にオン/オフ可能) に加えて、独自の設定可能なクイックアクセスフォルダーの一覧を持っています — <strong>設定 → プラグイン → Folder Cascader → 設定</strong> から、フォルダーのパスと任意の表示名を追加し、<code>Submenu</code> の値 (複数階層の場合は <code>Tools/Network</code> のように <code>/</code> 区切り) を指定すると、ルートに表示する代わりにカテゴリの下にネストできます。メニューのすべての階層 (ルートおよび各ネストされたカテゴリ) には、そのヘッダー自身に小さな <strong>+</strong> ボタンがあります。これをクリックすると、設定を開くためにメニューを離れることなく、現在閲覧中のフォルダーをその場で追加できます (名前・パス・その階層自身のサブメニューパスがあらかじめ入力された状態で、確定前にすべて編集可能です)。</p><h2 id="ハードコードされたキー-設定変更不可" tabindex="-1">ハードコードされたキー (設定変更不可) <a class="header-anchor" href="#ハードコードされたキー-設定変更不可" aria-label="Permalink to &quot;ハードコードされたキー (設定変更不可)&quot;">​</a></h2><p>これらは、ホットキーの設定に関係なく常に同じ動作をします:</p><table tabindex="0"><thead><tr><th>キー</th><th>コンテキスト</th><th>動作</th></tr></thead><tbody><tr><td><code>Escape</code></td><td>どこでも</td><td>テキストがあれば検索ボックスをクリアします。なければウィンドウを閉じます (またはアクションメニューを終了します)。</td></tr><tr><td><code>Enter</code></td><td>検索結果リスト</td><td>選択されている検索結果を開きます。</td></tr><tr><td><code>Ctrl+Enter</code></td><td>検索結果リスト</td><td>検索結果を開く代わりに、エクスプローラーで開く場所を表示します。</td></tr><tr><td><code>Ctrl+Shift+Enter</code></td><td>検索結果リスト</td><td>検索結果を昇格した権限で開きます (管理者として実行)。</td></tr><tr><td><code>Left</code> / <code>Right</code> 矢印キー</td><td>アクションメニュー</td><td>メニューの階層を戻る / サブメニューに入ります。</td></tr><tr><td><code>Backspace</code></td><td>アクションメニュー</td><td>検索ボックスがすでに空の場合、アクションメニューを終了します。</td></tr><tr><td><code>Alt+Space</code> / <code>Alt+F4</code></td><td>Lertaro のすべてのウィンドウ</td><td><code>Alt+Space</code> はすべてのウィンドウで無効化されています。いずれも本物のタイトルバーを持たず、Windows のシステムメニューが属する先がないためです。<code>Alt+F4</code> はメインウィンドウと設定ウィンドウでは通常どおりウィンドウを閉じます。クイックウィンドウ、インライン検索ウィンドウ、QuickLook、各種ダイアログでは引き続き無効化されています。これらは開いて閉じるものではなく、表示して隠すものだからです。</td></tr></tbody></table><h2 id="プラグインのアクションホットキー" tabindex="-1">プラグインのアクションホットキー <a class="header-anchor" href="#プラグインのアクションホットキー" aria-label="Permalink to &quot;プラグインのアクションホットキー&quot;">​</a></h2><p>プラグインは、既定のホットキーを持つ独自のアクションを登録できます (例えば、パスのコピー (<code>Ctrl+Shift+C</code>)、管理者として実行、あるいは組み込みのファイル操作 — カット <code>Ctrl+X</code>、コピー <code>Ctrl+C</code>、貼り付け <code>Ctrl+V</code>、削除 <code>Delete</code>、完全に削除 <code>Shift+Delete</code>)。これらは <strong>設定 → ホットキー → プラグインアクション</strong> に、登録したプラグインごとにグループ化されて表示され、組み込みのホットキーと同じ方法で再設定できます。</p><h2 id="プロセスのブラックリスト" tabindex="-1">プロセスのブラックリスト <a class="header-anchor" href="#プロセスのブラックリスト" aria-label="Permalink to &quot;プロセスのブラックリスト&quot;">​</a></h2><p>Lertaro のグローバルホットキーが別のアプリケーション (キーボードの生入力をキャプチャするゲームなど) と競合する場合は、そのプロセスを <strong>プロセスのブラックリスト</strong> に追加してください — <a href="./settings/hotkeys-page.html#process-blacklist">設定 → ホットキーページ</a>を参照してください。ブラックリストに登録されたプロセスが前面にある間は、Lertaro のグローバルホットキー、キー入力のインターセプト、そして上記のクイックナビゲーションのマウストリガーはすべてそのまま素通しされます。</p><p>本当にフルスクリーンで動作している前面のアプリには、ブラックリストへの登録なしで自動的に同じ扱いが適用されます。いずれの場合でも、アクティブなファイルダイアログは常に例外扱いとなり、そこではクイックナビゲーションが引き続き機能します。</p>',20)])])}const u=d(a,[["render",c]]);export{g as __pageData,u as default};
